CREATE TABLE IF NOT EXISTS p14_promotion_grants (season_index INT NOT NULL,server_id BIGINT NOT NULL,player_id BIGINT NOT NULL,grant_at BIGINT NOT NULL,observed_at BIGINT NOT NULL,points_before BIGINT NOT NULL,points_after BIGINT NOT NULL,rules_hash CHAR(64) NOT NULL,qualification_hash CHAR(64) NOT NULL,state_before_hash CHAR(64) NOT NULL,state_after_hash CHAR(64) NOT NULL,source_hash CHAR(64) NOT NULL,PRIMARY KEY(season_index,server_id,player_id,grant_at)) ENGINE=InnoDB;
